; // [intensity, time, flowSpeed, noiseScale]\nuniform vec4 u_liquidParams; // [waveFreq, waveAmp, 0, 0]\n\nout vec2 v_uv;\nout vec3 v_worldPos;\nout vec3 v_normal;\n\nvoid main() {\n    v_uv = a_uv;\n    vec3 pos = a_position;\n    \n    float time = u_extraParams.y;\n    float flowSpeed = u_extraParams.z;\n    float waveFrequency = u_liquidParams.x;\n    float waveAmplitude = u_liquidParams.y;\n\n    vec4 worldPos = u_model * vec4(pos, 1.0);\n    float displacementSpeed = time * flowSpeed * 0.5;\n    \n    // Wave based on world coordinates for seamless tiling\n    float wave = sin(worldPos.x * waveFrequency + displacementSpeed) * cos(worldPos.z * waveFrequency + displacementSpeed) * waveAmplitude;\n    pos.y += wave;\n\n    // Re-calculate worldPos with displacement\n    worldPos = u_model * vec4(pos, 1.0);\n    v_worldPos = worldPos.xyz;\n    v_normal = (u_model * vec4(a_normal, 0.0)).xyz;\n    gl_Position = u_vp * worldPos;\n}\n",fs:"#version 300 es\nprecision highp float;\n\nin vec2 v_uv;\nin vec3 v_worldPos;\nin vec3 v_normal;\n\nuniform vec4 u_color;\nuniform vec4 u_specColor;\nuniform float u_time;\nuniform float u_flowSpeed;\nuniform float u_noiseScale;\n\nuniform sampler2D u_diffuseMap;\nuniform sampler2D u_normalMap;\nuniform sampler2D u_specularMap;\nuniform sampler2D u_ambientMap;\n\nout vec4 FragColor;\n\nvoid main() {\n    // Use world position XZ for seamless tiling across objects\n    vec2 worldUV = v_worldPos.xz * 0.5; // Factor 0.5 because tile size was 2x2\n    vec2 uv = worldUV * u_noiseScale;\n    \n    vec2 uv1 = uv + vec2(u_time * 0.05, u_time * 0.02) * u_flowSpeed;\n    vec2 uv2 = uv + vec2(-u_time * 0.03, u_time * 0.04) * u_flowSpeed;\n    \n    float n1 = dot(texture(u_diffuseMap, uv1).rgb, vec3(0.299, 0.587, 0.114));\n    float n2 = dot(texture(u_diffuseMap, uv2).rgb, vec3(0.299, 0.587, 0.114));\n    float noise = (n1 + n2) * 0.5;\n    \n    // Ambient map for base details\n    vec4 ambient = vec4(1.0);\n    if (textureSize(u_ambientMap,